import sys

def min_spots(n, H):
    if H >= n:
        return 1
    if H == 1:
        return n
    k = (H * 2 - 1) // 2
    if n <= k * (k + 1):
        return int((1 + (1 + 8 * n) ** 0.5) / 2)
    else:
        remaining = n - k * (k + 1)
        return k + int((1 + (1 + 8 * remaining) ** 0.5) / 2)

def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    H = int(data[1])
    print(min_spots(n, H))

if __name__ == "__main__":
    main()
